import {MAP_LIBRARY_FILE,MAP_LIBRARY_KIND,MAP_ROLES,validSectorId,checkLibraryMarker,prepareVariant} from './sector-variant.js';
let selected=null;
const fileName=n=>typeof n==='string'&&/^[a-zA-Z0-9_-]+\.(json|svg|md)$/.test(n);
async function memory(value,write=false){const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('farmyard-commando-map-library-folder',1);r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});try{return await new Promise((resolve,reject)=>{const tx=db.transaction('settings',write?'readwrite':'readonly'),r=write?tx.objectStore('settings').put(value,'root'):tx.objectStore('settings').get('root');tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
export async function rememberedLibrary(){if(!selected)selected=await memory().catch(()=>null);return selected;}
export async function readText(dir,name){if(!fileName(name)&&name!==MAP_LIBRARY_FILE)throw Error('Invalid library filename.');return (await(await dir.getFileHandle(name)).getFile()).text();}
async function exists(dir,name){try{await dir.getFileHandle(name);return true;}catch(e){if(e.name==='NotFoundError')return false;throw e;}}
async function writeText(dir,name,text){const h=await dir.getFileHandle(name,{create:true}),stream=await h.createWritable();try{await stream.write(text);await stream.close();}catch(e){await stream.abort().catch(()=>{});throw e;}}
export async function validateFolder(handle){try{return checkLibraryMarker(JSON.parse(await readText(handle,MAP_LIBRARY_FILE)));}catch(e){if(e.name==='NotFoundError')throw Error('Choose the map library root containing '+MAP_LIBRARY_FILE+'. Use Create library for an empty folder.');throw e;}}
export async function chooseLibrary(){if(!window.showDirectoryPicker)throw Error('Direct folder access needs a browser with a directory picker, such as Chrome or Edge. You can still use Export JSON or the local workspace server.');const h=await window.showDirectoryPicker({id:'farmyard-commando-maps',mode:'readwrite'});await validateFolder(h);selected=h;await memory(h,true);return h;}
export async function requireLibrary(write=false){const h=await rememberedLibrary();if(!h)throw Error('Choose your map library folder first.');if(h.queryPermission&&await h.queryPermission({mode:write?'readwrite':'read'})!=='granted')throw Error('Folder permission expired. Choose the map library folder again to reconnect.');await validateFolder(h);return h;}
export async function folderCatalog(root){await validateFolder(root);const rows=[];for(const role of MAP_ROLES){let dir;try{dir=await root.getDirectoryHandle(role);}catch(e){if(e.name==='NotFoundError')continue;throw e;}for await(const [id,folder] of dir.entries()){if(folder.kind!=='directory')continue;if(!validSectorId(id))throw Error('Invalid configuration folder.');const entry=JSON.parse(await readText(folder,'placeholder.json'));if(entry.id!==id||!MAP_ROLES.includes(entry.role)||!Array.isArray(entry.allowedTransforms)||!Array.isArray(entry.variants))throw Error('Invalid configuration: '+id);if(rows.some(e=>e.id===id))throw Error('Duplicate configuration: '+id);rows.push({...entry,collectionRole:role});}}return rows.sort((a,b)=>a.id.localeCompare(b.id));}
async function findFolder(root,id){if(!validSectorId(id))throw Error('Invalid configuration.');const entry=(await folderCatalog(root)).find(e=>e.id===id);if(!entry)throw Error('Configuration missing from selected library: '+id);return {entry,dir:await(await root.getDirectoryHandle(entry.collectionRole)).getDirectoryHandle(id)};}
export async function readLibraryFile(id,name,role){const root=await requireLibrary();if(role){if(!MAP_ROLES.includes(role)||!validSectorId(id))throw Error('Invalid library path.');return readText(await(await root.getDirectoryHandle(role)).getDirectoryHandle(id),name);}const {dir}=await findFolder(root,id);return readText(dir,name);}
export async function saveFolderVariant(root,request){const work=()=>saveUnlocked(root,request);return globalThis.navigator?.locks?navigator.locks.request('aft-map-library-'+root.name+'-'+request.id,work):work();}
async function saveUnlocked(root,request){await validateFolder(root);const {dir,entry}=await findFolder(root,request.id),prepared=prepareVariant(entry,request),svg=request.name+'.svg';if(await exists(dir,prepared.filename)||await exists(dir,svg))throw Error('That variant already exists. Choose a new name.');
 // Publish metadata last. A write failure keeps the previous catalog usable.
 const before=await readText(dir,'placeholder.json');await writeText(dir,prepared.filename,JSON.stringify(prepared.map)+'\n');await writeText(dir,svg,prepared.preview);if(await readText(dir,'placeholder.json')!==before)throw Error('The configuration changed while saving. New files were retained; reload before registering them.');await writeText(dir,'placeholder.json',JSON.stringify(prepared.metadata,null,2)+'\n');return {id:entry.id,variant:prepared.filename,path:entry.collectionRole+'/'+entry.id+'/'+prepared.filename};
}
export async function createLibrary(){if(!window.showDirectoryPicker)throw Error('Creating a folder library needs Chrome or Edge, or the local workspace server.');const root=await window.showDirectoryPicker({id:'farmyard-commando-maps',mode:'readwrite'});for await(const _ of root.entries())throw Error('Choose an empty folder, preferably named AnimalFactoryMaps. Existing folders are never replaced.');
 const fetchText=async name=>{const r=await fetch(name);if(!r.ok)throw Error('Starter file unavailable: '+name);return r.text();};const index=JSON.parse(await fetchText('./sector-library/index.json'));
 for(const row of index.entries){if(!validSectorId(row.id))throw Error('Invalid configuration identifier.');const entry=JSON.parse(await fetchText('./sector-library/'+row.id+'/placeholder.json')),role=row.collectionRole||entry.role;if(!MAP_ROLES.includes(role))throw Error('Invalid role.');const dir=await(await root.getDirectoryHandle(role,{create:true})).getDirectoryHandle(row.id,{create:true});const files=new Set(['placeholder.json','preview.svg',...(entry.variants||[])]);if(entry.preview)files.add(entry.preview);for(const meta of Object.values(entry.variantDetails||{}))if(meta.preview)files.add(meta.preview);for(const name of files){if(!fileName(name))throw Error('Invalid starter filename.');await writeText(dir,name,await fetchText('./sector-library/'+row.id+'/'+name));}}
 await writeText(root,MAP_LIBRARY_FILE,JSON.stringify({kind:MAP_LIBRARY_KIND,version:1,name:'AnimalFactoryMaps'},null,2)+'\n');selected=root;await memory(root,true);return root;
}
export function downloadText(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
